"""Keep broadband reverse-cymbal noise out of the tonal/modal loop fitter.

The SF2 reverse cymbal is a noise carrier with a 1.5s amplitude attack.
Peak-picking its spectrum produces a pitched buzz; retaining native noise
and scheduling the slow envelope preserves the sound without runtime DSP.
"""
import math,copy

def install(owner):
    import mussc as m
    for z in list(owner.zones):
        if not z.notes or z.notes[0].preset != (0,119):continue
        r=z.r;rate=float(z.s.rate);L=2047
        # Keep source rate/high partials. Eight times the old modal carrier
        # length, with all noise bins retained rather than selected peaks.
        src=list(z.s.data[r.start:r.end])
        if z.fc_hz:src=m.biquad(src,rate,z.fc_hz/z.s_mid,r.g.get('initialFilterQ',0))
        cyc=src[r.ls:r.ls+L]
        # A short equal-power overlap joins two uncorrelated noise segments.
        X=48
        for i in range(X):
            t=(i+.5)/X
            cyc[i]=cyc[i]*math.sin(t*math.pi/2)+src[r.ls+L+i]*math.cos(t*math.pi/2)
        dc=sum(cyc)/len(cyc);cyc=[v-dc for v in cyc];cyc.append(cyc[0])
        z.kind='loop';z.loop_len=0;z.nat=z.nat_len=0.;z.attack=0.
        z.noise_attack=True;z.inharm=False;z.morph_basis=None
        owner.finish(z,cyc,None,rate)
        if owner.name=='D_E1M5':
            # Quiet reverb falls below a single DOC volume step. A4-page
            # carrier24dB down extends the fade using the same oscillator.
            q=copy.copy(z);q.name='p119/wet_tail_atten24';q.kind='loop'
            q.notes=[];q.morph_basis=None
            a=list(z.table[:1023]);a.append(a[0])
            q.table=bytes(max(1,min(255,128+round((v-128)/16))) for v in a)
            q.size=1024;q.ltable=b'';q.loop_len=0;q.morph_family=[]
            z.morph_family=[z,q];z.quiet_tail=True;owner.zones.append(q)
            for n in owner.notes:
                if n.z is not z:continue
                curve=WET_DB[round(n.on/140)];pk=min(range(len(curve)),key=curve.__getitem__)
                # Switch at 24dB down so the +24dB volume compensation
                # returns to the peak volume instead of exceeding it.
                i=next(i for i in range(pk,len(curve)) if curve[i]>=24)
                n.quiet_at=n.on+round(i*0.01*140)
    owner.layout()

