def tail_tics(on):
    curve=WET_DB[round(on/140)]
    return round((len(curve)-1)*0.01*140)

def wet_db(t,on):
    curve=WET_DB[round(on/140)]
    x=max(0.,t*100);i=int(x)
    if i>=len(curve)-1:return 100.
    return max(0.,curve[i]+(curve[i+1]-curve[i])*(x-i))
